/* CSS CHÍNH: Nền đen, Tiêu đề trắng, Body trắng, Font Roboto Condensed, KHÔNG KHUNG */
        body {
            font-family: 'Roboto Condensed', sans-serif;
            line-height: 1.6;
            color: #FFFFFF; /* TOÀN BỘ CHỮ BODY MÀU TRẮNG */
            margin: 0;
            padding: 0;
            background-color: #000000; /* Nền màu ĐEN TUYỆT ĐỐI */
        }
        .container {
            max-width: 900px;
            margin: 20px auto;
            padding: 20px 30px; /* Giữ padding để nội dung không sát lề */
        }
        h1, h2, h3, h4 {
            color: #FFFFFF; /* MÀU TRẮNG cho tiêu đề */
            font-weight: 700;
            text-transform: uppercase;
            font-family: 'Roboto Condensed' !important; /* Đảm bảo font */
        }
        h1 {
            font-size: 2.5em;
            border-bottom: 3px solid #330000;
            padding-bottom: 15px;
            margin-bottom: 25px;
            text-align: center;
            letter-spacing: 1px;
        }
        h2 {
            font-size: 1.8em;
            margin-top: 30px;
            border-left: 5px solid #cc0000; /* Đỏ cho đường kẻ bên trái */
            padding-left: 10px;
        }
        h3 {
             font-size: 1.3em; /* Tiêu đề con */
             margin-top: 20px;
             color: #ff3333; /* Màu đỏ sáng cho tiêu đề con */
        }
        h4 {
             font-size: 1.1em; /* Tiêu đề phụ nhỏ hơn */
             margin-top: 15px;
             color: #ffcc00; /* Màu vàng cho sub-title */
        }
        p {
            margin-bottom: 15px;
            color: #FFFFFF; /* TOÀN BỘ CHỮ ĐOẠN VĂN MÀU TRẮNG */
        }
        .highlight {
            font-weight: bold;
            color: #FFFFFF; /* Màu trắng cho highlight */
        }
        .note {
            background-color: #331a1a;
            padding: 15px;
            border-left: 5px solid #ffcc00;
            margin: 20px 0;
            border-radius: 5px;
            color: #f0f0f0;
        }
        /* Link trong bài */
        a {
            color: #ff3333; 
            text-decoration: none;
        }
        a:hover {
            text-decoration: underline;
        }
        ul {
            padding-left: 25px;
            margin-bottom: 20px;
        }
        li {
            margin-bottom: 10px;
        }
        code {
            background-color: #331a1a;
            padding: 2px 4px;
            border-radius: 3px;
            color: #ffcc00; /* Màu vàng cho phím tắt */
        }
