/* ----------------------------------------------------------------
   XEM THEM BLOCK — standalone <div class="xem-them"> only
---------------------------------------------------------------- */
div.xem-them {
    display: block;
    box-sizing: border-box;
    width: 100%;
    background-color: #1a1200;
    border-top: 1px solid #7a5500;
    border-right: 1px solid #7a5500;
    border-bottom: 1px solid #7a5500;
    border-left: 4px solid #ffaa33;
    border-radius: 4px;
    padding: 11px 16px;
    margin: 20px 0 24px 0;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 0.95em;
    font-weight: 700;
    color: #ffaa33;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    line-height: 1.5;
}
div.xem-them a {
    color: #ffcc77;
    text-decoration: none;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
div.xem-them a:hover {
    color: #ffe8aa;
    text-decoration: underline;
}

/* --- TABLE --- */
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}
table td, table th {
    border: 1px solid #440000;
    padding: 10px 12px;
    color: #ffffff;
    vertical-align: top;
}
table tr:first-child td {
    background-color: #1a0000;
    font-weight: 700;
    color: #ffcc00;
}
table tr:not(:first-child):nth-child(even) td {
    background-color: #0d0d0d;
}
